{
  "decision": "BLOCK",
  "findings": [
    {
      "severity": "high",
      "file": "cloud_pilot/multilingual/__main__.py; cloud_pilot/multilingual/editorial_state.py",
      "detail": "Before source transfers, execute begins research for every article lacking a checkpoint in the current scoped journal. A new code or evidence epoch has a new checkpoint namespace, so begin() can lock and mark an existing accepted head UPDATE_REQUIRED for both articles before either transfer is attempted. A failure affecting one article can therefore invalidate the unrelated article despite record_transfer_failure() itself being article-specific.",
      "required_fix": "Acquire each article's research fence immediately before its own transfer or refresh, rather than pre-locking the whole batch. Add an end-to-end regression with two previously accepted heads, a new epoch, and one failed transfer; verify that the other head and readiness remain unchanged."
    },
    {
      "severity": "high",
      "file": "cloud_pilot/live/engine.py; cloud_pilot/multilingual/__main__.py; cloud_pilot/multilingual/publication.py",
      "detail": "The synchronized batch manifest is written only on the path to writing. Source-transfer, source-retrieval, invalid-research and non-ready-research failures persist article records and then stop without updating the manifest. The latest batch manifest can consequently retain PENDING statuses and zero failure counts after a recorded failure, or retain a stale pending row after another article has progressed.",
      "required_fix": "Synchronize and durably identify the current batch manifest after every research state transition, including failure and withheld outcomes. Add end-to-end tests that inspect the manifest and counts after each failure path and after a partial batch."
    }
  ],
  "human_reviewed": false,
  "publish_approved": false
}
